// The sample's carried-tray pose (M5 W7, AB-T-0609): animations/clips/carry.vrma, a looped two-second clip with both
// forearms held level in front at the waist, generated by the character fixtures' clip writer (CC0, no capture). It
// plays on a character's upperBody layer while she walks (engine/packages/character/LAYERS.md). It is not in
// animations.json yet: adding a clip there gives every character a mixer action whose lower-arm bindings the mixer then
// writes every step, which can move the replay of scenes with a hand reach, so the sample game (W10) adds it with its
// own re-check; until then the layer checks (apps/playground/src/layers-check.js) add it to the document they load.
//   node content/sample/tools/make-carry.mjs [--check]
// Needs vrmxa-core beside the repo (it writes the .vrma).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { makeClip, vrmxaCore } from '../../../engine/packages/character/test/fixtures.mjs';

const content = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const CARRY = 'animations/clips/carry.vrma';
const core = await vrmxaCore();
const bytes = makeClip(core, 'carry', { seconds: 2, carry: 1 });
const file = path.join(content, CARRY);
if (process.argv.includes('--check')) {
  const same = fs.existsSync(file) && Buffer.compare(fs.readFileSync(file), Buffer.from(bytes)) === 0;
  console.log(same ? `${CARRY} is up to date` : `${CARRY} differs from what this tool makes`);
  process.exit(same ? 0 : 1);
}
fs.writeFileSync(file, bytes);
console.log(JSON.stringify({ sha256: await core.sha256(bytes), file: CARRY, name: 'carry', duration: 2, loops: true, rootMotion: 'inPlace', tracks: ['humanoid'], licence: 'CC0-1.0', source: 'generated by engine/packages/character/test/fixtures.mjs' }, null, 1));
